<template>
 <view class="wizard">
  <recruitment-conflict v-if="conflictSnapshot" :rows="conflictRows" :busy="busy" :can-replace="canReplace" :blocked-message="conflictBlockedMessage" :error="submitError" @close="closeConflict" @view="viewActive" @replace="replaceFromConflict"/>
  <app-toast :message="validationToast" type="error"/>
  <view class="steps" role="navigation" aria-label="发布步骤"><view class="step-rail"><view class="step-progress" :style="{width:((step-1)/3*100)+'%'}"/></view>
   <button v-for="(name,index) in stepNames" :key="name" :class="{active:step===index+1,done:step>index+1}" :aria-current="step===index+1?'step':undefined" @click="go(index+1)"><text class="step-no">{{index+1}}</text><text>{{name}}</text></button>
  </view>
  <view v-if="saveFailed" class="draft-warning" role="status"><text>{{saveIssue}}</text><button @click="saveDraft">重试保存</button></view>
  <view v-if="step===1" class="wizard-panel">
   <view class="section-heading">合作目的<text>选择这局主要做什么</text></view>
   <view class="purpose-grid"><button v-for="g in GOALS" :key="g" :class="{chosen:form.goal===g}" :aria-pressed="form.goal===g" @click="form.goal=g"><b>{{g}}</b><text>{{goalNotes[g]}}</text></button></view>
   <view v-if="errors.goal" class="error-line">{{errors.goal}}</view>
   <view v-if="form.goal==='33任务'" class="section-block"><view class="subheading">33任务 <text>可多选</text></view><view v-for="group in TASK_GROUPS" :key="group.label" class="task-group"><text class="muted-label">{{group.label}}</text><view class="chips"><button v-for="task in group.values" :key="task" :class="{chosen:form.tasks.includes(task)}" :aria-pressed="form.tasks.includes(task)" @click="toggleTask(task)">{{form.tasks.includes(task)?'✓ ':''}}{{task}}</button></view></view><view v-if="errors.tasks" class="error-line">{{errors.tasks}}</view></view>
   <view class="section-block"><view class="subheading">开局时段</view><view class="slot-field"><dark-select :model-value="form.slot" @update:model-value="selectSlot" :options="SLOT_OPTIONS" label="开局时段" placeholder="请选择开局时段" :invalid="!!errors.slot"/></view></view>
  </view>
  <view v-if="step===2" class="wizard-panel">
   <view class="section-heading">地图与难度<text>可添加多张地图，每张选择一个难度</text></view>
   <view class="map-choices"><button v-for="map in Object.keys(MAP_MODES)" :key="map" :class="{chosen:hasMap(map)}" :aria-pressed="hasMap(map)" @click="toggleMap(map)" :title="hasMap(map)?'点击取消选择':'点击选择地图'">{{hasMap(map)?'✓':'＋'}} {{map}}</button></view>
   <view class="map-pairs">
   <view v-for="pair in form.maps" :key="pair.map" class="map-pair"><view class="pair-head"><b>{{pair.map}}</b><button :aria-label="'移除'+pair.map" class="remove-map" @click="removeMap(pair.map)">×</button></view><view class="chips"><button v-for="mode in MAP_MODES[pair.map]" :key="mode" :class="{chosen:pair.difficulty===mode,night:mode==='机密·黑夜'}" :aria-pressed="pair.difficulty===mode" @click="pair.difficulty=mode">{{mode}}</button></view></view>
   </view>
   <view v-if="!form.maps.length" class="empty-map">从上方选择本次可以玩的地图</view>
  </view>
  <view v-if="step===3" class="wizard-panel">
   <view class="section-heading">自身配置<text>填写个人资料与本局配置</text></view>
   <view class="basic-info-section"><view class="basic-info-heading"><view class="subheading">基础信息<help-tooltip label="登录与匿名参与说明" text="手机号登录后可在其他设备恢复常用资料；也可以不登录，直接参与组队，常用填写内容会保存在当前浏览器"/></view><phone-login :profile="personalProfile" @restore="restoreProfile"/></view><view class="basic-grid"><label :class="{invalid:errors.nickname}"><view class="field-label">队内昵称 <text class="required">*</text></view><input v-model="form.nickname" maxlength="24" placeholder="怎么称呼你" placeholder-style="color:#718096"/><text v-if="errors.nickname" class="error-line">{{errors.nickname}}</text></label><view v-for="field in baseFields" :key="field.key" class="basic-field">{{field.label}}<dark-select v-model="form[field.key]" :options="field.values" :label="field.label"  :option-labels="field.labels||{}"/></view><view class="basic-field" :class="{invalid:errors.style}">我的打法风格<dark-select :model-value="form.style==null?'':String(form.style)" :options="styleOptions" :option-labels="styleOptionLabels" label="我的打法风格" @update:model-value="form.style=Number($event)"/><text v-if="errors.style" class="error-line">{{errors.style}}</text></view></view></view>
   <view v-if="needsGear" class="subheading section-block">我的装备</view>
   <view v-if="needsGear" class="gear-list"><view v-for="gear in GEAR_FIELDS" :key="gear.key" class="choice-row"><text class="row-label">{{gear.label}}</text><view class="level-group"><button v-for="n in 6" :key="n" :class="{chosen:form[gear.key]===n}" :aria-pressed="form[gear.key]===n" @click="form[gear.key]=n">{{n}}<text>级</text></button></view><view v-if="errors[gear.key]" class="error-line row-error">{{errors[gear.key]}}</view></view></view>

   <view class="section-block strength-section"><view class="strength-heading"><view class="subheading strength-title">硬核实力<text class="guidance">请按真实数据填写，实力差距过大会影响双方体验</text></view></view>
    <view class="strength-values">
    <view class="stats-grid"><label v-for="field in scoreFields" :key="field.key" :class="{invalid:errors[field.key]}"><view class="field-label">{{field.label}}<text class="required">*</text><text v-if="empty(form[field.key])" class="missing">待填写</text></view><input v-model.number="form[field.key]" type="digit" :placeholder="field.placeholder" placeholder-style="color:#718096" @blur="checkField(field.key)"/><text v-if="errors[field.key]" class="error-line">{{errors[field.key]}}</text></label></view>

    <strength-score :value="myScore"/>
    </view>
    <view v-if="scoreError" class="error-line" role="alert">{{scoreError}}<button class="score-retry" @click="calculateScore">重试计算</button></view>
   </view>
  </view>
  <view v-show="step===4" class="wizard-panel">
   <view class="section-heading">队友要求<text>同时满足彼此要求才会匹配</text></view>
   <view class="partner-ranges" role="group" aria-label="队友打法与实力范围">
    <view class="partner-range"><view class="subheading">可接受的打法范围<help-tooltip label="打法范围说明" text="1 很保守 — 5 很激进，队友的打法需在最低与最高档之间"/></view><view class="style-bounds"><view v-for="bound in styleBounds" :key="bound.key" class="style-bound"><text class="muted-label">{{bound.label}}</text><view class="level-group"><button v-for="n in 5" :key="n" :class="{chosen:form[bound.key]===n}" :aria-label="bound.label+'打法 '+n+' 档'" :aria-pressed="form[bound.key]===n" @click="form[bound.key]=n">{{n}}</button></view></view></view><view v-if="errors.partner_style" class="error-line">{{errors.partner_style}}</view></view>
    <view class="partner-range"><view class="subheading">队友实力范围<help-tooltip label="队友实力范围说明" tone="warning" text="在我的分数基础上，默认加减 30%，拖动滑杆可调整容差"/><button v-if="form.strength_range_mode!=='auto'" class="range-action" @click="setTolerance(30)">恢复默认</button></view>
     <view class="tolerance-summary"><text class="tolerance-percent">{{form.strength_range_mode==='custom'?'已保存范围':'±'+tolerancePercent+'%'}}</text><text class="tolerance-score">{{myScore===null?'待填写实力数据':range.map(formatRange).join(' — ')+' 分'}}</text></view>
     <view class="tolerance-control" role="slider" tabindex="0" aria-label="队友实力容差" :aria-valuemin="0" :aria-valuemax="100" :aria-valuenow="tolerancePercent" :aria-valuetext="'正负 '+tolerancePercent+'%'" :aria-disabled="myScore===null" @keydown.left.prevent="setTolerance(tolerancePercent-1)" @keydown.down.prevent="setTolerance(tolerancePercent-1)" @keydown.right.prevent="setTolerance(tolerancePercent+1)" @keydown.up.prevent="setTolerance(tolerancePercent+1)" @keydown.home.prevent="setTolerance(0)" @keydown.end.prevent="setTolerance(100)"><slider :min="0" :max="100" :step="1" :value="tolerancePercent" :disabled="myScore===null" activeColor="#b9f477" backgroundColor="#344458" block-color="#c7f49b" :block-size="16" @changing="onToleranceChange" @change="onToleranceChange"/><view class="tolerance-scale"><text>0%</text><text class="tolerance-default">30% 默认</text><text>100%</text></view></view>
     <text v-if="form.strength_range_mode==='custom'" class="legacy-range-note">拖动后按我的分数对称调整</text><view v-if="errors.strength_range" class="error-line">{{errors.strength_range}}</view>
    </view>
   </view>
   <view v-if="needsGear" class="section-block"><view class="subheading">队友最低装备<text>不高于自己的对应装备</text></view><view v-for="gear in GEAR_FIELDS" :key="gear.key" class="choice-row"><text class="row-label">{{gear.label}}</text><view class="level-group"><button v-for="n in 6" :key="n" :class="{chosen:form['partner_'+gear.key+'_min']===n}" :disabled="n>form[gear.key]" @click="form['partner_'+gear.key+'_min']=n">{{n}}<text>级</text></button></view><view v-if="errors['partner_'+gear.key+'_min']" class="error-line row-error">{{errors['partner_'+gear.key+'_min']}}</view></view></view>

   <view class="section-block recruitment-settings"><view class="subheading">发布设置</view><view class="recruitment-settings-row"><view class="discovery-settings"><view class="settings-label"><text class="settings-title">招募方式</text><help-tooltip label="招募方式说明" :items="discoveryHelp"/></view><view class="mode-toggle" role="group" aria-label="招募方式"><button :class="{chosen:form.discovery==='browse'}" :aria-pressed="form.discovery==='browse'" @click="form.discovery='browse'">自己挑选</button><button :class="{chosen:form.discovery==='auto'}" :aria-pressed="form.discovery==='auto'" @click="form.discovery='auto'">自动匹配</button></view></view><view class="visibility-settings"><text>开启在大厅公开招募</text><button class="visibility-toggle" :class="{enabled:form.public}" role="switch" :aria-checked="form.public" aria-label="在大厅公开招募" @click="form.public=!form.public"><text/></button></view></view></view>
  </view>
  <view v-if="preview" class="publish-overlay" @click.self="closePreview"><view class="publish-dialog" role="dialog" aria-modal="true" aria-label="发布前确认" tabindex="-1" @keydown.esc.stop="closePreview" @keydown.tab="trapPreviewFocus">
   <view class="publish-head"><view><b>发布前确认</b><text>确认招募条件，发布后即可寻找队友</text></view><button class="preview-close" tabindex="0" aria-label="关闭招募预览" :disabled="busy" @click="closePreview">×</button></view>
   <view class="publish-content">
    <view class="preview-line"><text class="preview-key">合作目的</text><view class="preview-tags"><text class="purpose-tag">{{form.goal}}</text></view></view>
    <view class="preview-line"><text class="preview-key">地图与难度</text><view class="preview-tags"><text v-for="m in form.maps" :key="m.map">{{m.map}} · {{m.difficulty}}</text></view></view>
    <view v-if="form.goal==='33任务'" class="preview-line"><text class="preview-key">任务</text><view class="preview-tags"><text v-for="task in form.tasks" :key="task">{{task}}</text></view></view>
    <view class="preview-comparison"><view class="preview-column"><view class="preview-column-title">我的配置</view><view v-if="needsGear" class="preview-metric"><text>装备</text><b>头{{form.helmet}} · 甲{{form.armor}} · 弹{{form.ammo}}</b></view><view class="preview-metric"><text>打法</text><b>{{form.style}} · {{STYLE_LABELS[form.style-1]}}</b></view><view class="preview-metric"><text>实力</text><b>{{myScore}} 分</b></view></view><view class="preview-column"><view class="preview-column-title">队友要求</view><view v-if="needsGear" class="preview-metric"><text>装备</text><b>头≥{{form.partner_helmet_min}} · 甲≥{{form.partner_armor_min}} · 弹≥{{form.partner_ammo_min}}</b></view><view class="preview-metric"><text>打法</text><b>{{form.partner_style_min}}–{{form.partner_style_max}} 档</b></view><view class="preview-metric"><text>实力</text><b>{{range[0]}}–{{range[1]}} 分</b></view></view></view>
    <view class="preview-summary">
     <view class="preview-line"><text class="preview-key">基础信息</text><view class="preview-tags"><text>{{form.nickname}}</text><text>{{form.region}}</text><text>{{{PC:'电脑端',Console:'主机端',Mobile:'手机端'}[form.platform]}}</text><text>{{form.language}}</text><text>{{form.voice}}</text></view></view>
     <view class="preview-line"><text class="preview-key">开局时段</text><view class="preview-tags"><text>{{form.slot}}</text></view></view>
     <view class="preview-line"><text class="preview-key">发布设置</text><view class="preview-tags"><text>{{form.discovery==='auto'?'自动匹配':'自己挑选'}}</text><text>{{form.public?'公开招募':'不公开招募'}}</text></view></view>
    </view>
    <view v-if="submitError" class="preview-submit-error" role="alert">{{submitError}}</view>
   </view>
   <view class="publish-footer"><button tabindex="0" :disabled="busy" @click="closePreview">返回修改</button><button v-if="activeTicket" tabindex="0" class="publish-confirm" :disabled="busy" @click="openConflict">提交本次组队</button><button v-else tabindex="0" class="publish-confirm" :disabled="busy" @click="finish">{{busy?'发布中…':'确认发布'}}</button></view>
  </view></view>
  <view class="wizard-actions"><button class="save-draft" @click="saveDraft">{{saved?'✓ 已保存到本地':'保存到本地'}}</button><view class="nav-buttons"><button v-if="step>1" @click="go(step-1)">上一步</button><button v-if="activeTicket" class="primary" :disabled="busy" @click="openConflict">提交本次组队</button><button v-else-if="step<4" class="primary" @click="next">下一步</button><button v-else class="primary" :disabled="busy" @click="finish">{{busy?'发布中…':'预览招募'}}</button></view></view>
 </view>
</template>
<script setup>
import {computed,reactive,ref,watch,nextTick,onBeforeUnmount} from 'vue'
import {toleranceBounds} from '../utils/strength-range.js'
import RecruitmentConflict from './recruitment-conflict.vue'
import {recruitmentComparison} from '../utils/recruitment-comparison.js'
import AppToast from './app-toast.vue'
import DarkSelect from './dark-select.vue'
import StrengthScore from './strength-score.vue'
import PhoneLogin from './phone-login.vue'
import HelpTooltip from './help-tooltip.vue'
import {MAP_MODES,GOALS,SLOT_OPTIONS,TASK_GROUPS,STYLE_LABELS,GEAR_FIELDS,scoreInputsValid} from '../utils/recruitment-options.js'
import {loadPreferences,savePreferencesDetailed,pickPreferences} from '../utils/pilot-preferences.js'
import {authRequest} from '../utils/pilot-session.js'
import {stepErrors} from '../utils/recruitment-validation.js'
const props=defineProps({busy:Boolean,activeTicket:Boolean,submitError:String,importProfile:Object,existingTicket:Object,squadStatus:String,resumeDraft:Object})
const emit=defineEmits(['submit','clear-error','view-active','replace','draft-change'])
const loaded=props.resumeDraft?{values:pickPreferences(props.resumeDraft),found:true}:loadPreferences(uni)
const form=reactive(loaded.values),step=ref(form.wizard_step),errors=ref({}),saveFailed=ref(false),saveIssue=ref(''),saved=ref(false),preview=ref(false)
const validationToast=ref('')
let validationToastTimer=null
function showValidation(found){const message=found.maps||found.slot;if(message){clearTimeout(validationToastTimer);validationToast.value=message;validationToastTimer=setTimeout(()=>{validationToast.value=''},6000)}}
onBeforeUnmount(()=>clearTimeout(validationToastTimer))
watch(step,()=>{clearTimeout(validationToastTimer);validationToast.value=''})
watch(()=>form.maps.map(m=>m.map+':'+m.difficulty).join('|'),()=>{if(!stepErrors(form,2).maps){clearTimeout(validationToastTimer);validationToast.value=''}})
let lastSaveError=''
watch(()=>props.importProfile,value=>{if(!value)return;Object.assign(form,pickPreferences({...value,wizard_step:1}));step.value=1;errors.value={};preview.value=false;persistDraft()},{immediate:true})
function persistDraft(){emit('draft-change',JSON.parse(JSON.stringify(form)));const result=savePreferencesDetailed(uni,form);saveFailed.value=!result.ok;saveIssue.value=result.message||'';const diagnostic=result.ok?'':result.stage+':'+result.errorName+':'+result.reason;if(diagnostic&&diagnostic!==lastSaveError)console.warn('[draft-save]',diagnostic);lastSaveError=diagnostic;return result.ok}
const discoveryHelp=[{id:'browse',title:'自己挑选',description:'在招募大厅查看玩家条件，主动申请组队，双方确认后组成队伍'},{id:'auto',title:'自动匹配',description:'系统在选择自动匹配的在线玩家中，寻找双方条件相符的队友，找到后仍需双方确认'},{id:'public',title:'大厅公开招募',description:'开启后，其他玩家可在大厅看到你的招募并主动申请；关闭后不在大厅展示，不影响自动匹配'}]
const styleBounds=[{key:'partner_style_min',label:'最低'},{key:'partner_style_max',label:'最高'}]
const stepNames=['合作目的','地图与难度','自身配置','队友要求']
const goalNotes={'33任务':'完成保险箱相关任务','卡战备跑刀':'轻装搜集','搜打撤':'搜集物资，择机交战','猛攻':'主动寻找交战'}
const scoreFields=[{key:'confidential_kd',label:'机密 KD',placeholder:'例如 1.5'},{key:'top_secret_kd',label:'绝密 KD',placeholder:'例如 2.0'},{key:'combat_score',label:'战斗分',placeholder:'例如 50'}]
const baseFields=[{key:'region',label:'区服',values:['NA','EU','SEA','OCE','ME']},{key:'platform',label:'游戏端',values:['PC','Console','Mobile'],labels:{PC:'电脑端',Console:'主机端',Mobile:'手机端'}},{key:'language',label:'沟通语言',values:['中文','English','日本語']},{key:'voice',label:'语音方式',values:['开麦','听指挥与标记']}]
const styleOptions=STYLE_LABELS.map((_,i)=>String(i+1))
const styleOptionLabels=Object.fromEntries(STYLE_LABELS.map((label,i)=>[String(i+1),(i+1)+' '+label]))
const personalKeys=['nickname','region','platform','language','voice','helmet','armor','ammo','style','confidential_kd','top_secret_kd','combat_score']
const personalProfile=computed(()=>Object.fromEntries(personalKeys.map(k=>[k,form[k]])))
function restoreProfile(values){for(const key of personalKeys)if(Object.prototype.hasOwnProperty.call(values,key))form[key]=values[key]??(['helmet','armor','ammo'].includes(key)?null:'')}
const needsGear=computed(()=>form.goal!=='卡战备跑刀'),scoreResult=ref(null),scoreError=ref('')
const myScore=computed(()=>scoreResult.value?.strength_score??null),tolerancePercent=computed(()=>form.strength_range_mode==='auto'?30:form.strength_tolerance_percent),range=computed(()=>form.strength_range_mode==='custom'?[form.strength_min,form.strength_max]:toleranceBounds(myScore.value,tolerancePercent.value))
const conflictSnapshot=ref(null)
const conflictRows=computed(()=>conflictSnapshot.value?recruitmentComparison(conflictSnapshot.value.profile,form,myScore.value,range.value):[])
const canReplace=computed(()=>!!conflictSnapshot.value&&props.existingTicket?.id===conflictSnapshot.value.id&&props.existingTicket?.status==='waiting'&&!['proposed','ready'].includes(props.squadStatus))
const conflictBlockedMessage=computed(()=>props.existingTicket?.status==='matched'||['proposed','ready'].includes(props.squadStatus)?'已匹配到队友，请先查看并处理现有队伍':props.existingTicket?.id!==conflictSnapshot.value?.id?'招募已变化，请先查看当前招募后重新选择':'原招募已结束，请返回后重新发布')
let scoreTimer=null,scoreRequest=0,scoreDisposed=false
const scoreKey=()=>JSON.stringify([form.confidential_kd,form.top_secret_kd,form.combat_score])
async function calculateScore(){
 clearTimeout(scoreTimer);const request=++scoreRequest,key=scoreKey();scoreError.value=''
 if(!scoreInputsValid(form)){scoreResult.value=null;return false}
 try{const result=await authRequest('strength-preview',Object.fromEntries(['confidential_kd','top_secret_kd','combat_score'].map(k=>[k,Number(form[k])])));if(scoreDisposed||request!==scoreRequest||key!==scoreKey())return false;scoreResult.value=result;return true}
 catch(e){if(!scoreDisposed&&request===scoreRequest){scoreResult.value=null;scoreError.value=e.message||'实力分计算失败，请重试'}return false}
}
watch(scoreKey,()=>{++scoreRequest;clearTimeout(scoreTimer);scoreResult.value=null;scoreError.value='';if(scoreInputsValid(form))scoreTimer=setTimeout(calculateScore,400)},{immediate:true})
onBeforeUnmount(()=>{scoreDisposed=true;++scoreRequest;clearTimeout(scoreTimer)})
const empty=n=>n===''||n==null
watch(form,()=>{saved.value=false;preview.value=false;persistDraft();if(Object.keys(errors.value).length)errors.value=stepErrors(form,step.value)},{deep:true,flush:'post'})
for(const gear of GEAR_FIELDS)watch(()=>form[gear.key],n=>{const k='partner_'+gear.key+'_min';if(n!=null&&form[k]>n)form[k]=null})
defineExpose({getDraft:()=>JSON.parse(JSON.stringify(form))})
function saveDraft(){saved.value=persistDraft()}
function selectSlot(value){form.slot=value;form.slot_explicit=true;clearTimeout(validationToastTimer);validationToast.value=''}
function toggleTask(task){form.tasks=form.tasks.includes(task)?form.tasks.filter(t=>t!==task):[...form.tasks,task]}
function hasMap(map){return form.maps.some(m=>m.map===map)}
function toggleMap(map){if(hasMap(map))removeMap(map);else form.maps.push({map,difficulty:''})}
function removeMap(map){form.maps=form.maps.filter(m=>m.map!==map)}
function scrollTop(){uni.pageScrollTo({scrollTop:0,duration:200})}
function go(n){if(n>step.value){for(let i=1;i<n;i++){const found=stepErrors(form,i);if(Object.keys(found).length){step.value=i;form.wizard_step=i;errors.value=found;preview.value=false;nextTick(()=>showValidation(found));scrollTop();return}}}step.value=n;form.wizard_step=n;errors.value={};preview.value=false;scrollTop()}
function next(){go(step.value+1)}
function checkField(key){const found=stepErrors(form,step.value);if(found[key])errors.value={...errors.value,[key]:found[key]}}
const formatRange=value=>new Intl.NumberFormat('en-US',{maximumFractionDigits:2}).format(value)
function setTolerance(value){if(myScore.value===null)return;const percent=Math.max(0,Math.min(100,Math.round(Number(value))));if(!Number.isFinite(percent))return;form.strength_tolerance_percent=percent;form.strength_range_mode=percent===30?'auto':'percent'}
function onToleranceChange(event){setTolerance(event.detail.value)}
let oldBodyOverflow='',oldRootOverflow='',locked=false,previousFocus=null
function viewActive(){persistDraft();preview.value=false;conflictSnapshot.value=null;emit('view-active')}
async function openConflict(){if(props.busy)return;emit('clear-error');preview.value=false;await nextTick();if(!props.existingTicket){viewActive();return}conflictSnapshot.value=JSON.parse(JSON.stringify(props.existingTicket))}
function closeConflict(){if(props.busy)return;conflictSnapshot.value=null;emit('clear-error')}
async function replaceFromConflict(){if(props.busy||!canReplace.value)return;const expected=conflictSnapshot.value.id,payload=await preparePayload();if(!payload||props.busy)return;emit('replace',{expected_ticket_id:expected,profile:payload})}
function closePreview(){if(!props.busy)preview.value=false}
function unlockPreview(){if(!locked||typeof document==='undefined')return;document.body.style.overflow=oldBodyOverflow;document.documentElement.style.overflow=oldRootOverflow;locked=false;previousFocus?.focus?.()}
watch(preview,async shown=>{
 if(typeof document==='undefined')return
 if(shown){oldBodyOverflow=document.body.style.overflow;oldRootOverflow=document.documentElement.style.overflow;previousFocus=document.activeElement;document.body.style.overflow='hidden';document.documentElement.style.overflow='hidden';locked=true;await nextTick();document.querySelector('.publish-dialog')?.focus()}
 else unlockPreview()
})
function trapPreviewFocus(event){if(typeof document==='undefined')return;const elements=[...document.querySelectorAll('.publish-dialog [tabindex="0"]')].filter(el=>!el.hasAttribute('disabled'));if(!elements.length)return;const first=elements[0],last=elements[elements.length-1];if(event.shiftKey&&(document.activeElement===first||document.activeElement===document.querySelector('.publish-dialog'))){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}
onBeforeUnmount(unlockPreview)
async function preparePayload(){
 for(let i=1;i<=4;i++){const found=stepErrors(form,i);if(Object.keys(found).length){step.value=i;form.wizard_step=i;errors.value=found;preview.value=false;conflictSnapshot.value=null;nextTick(()=>showValidation(found));scrollTop();return null}}
 if(myScore.value===null&&!await calculateScore()){step.value=3;form.wizard_step=3;conflictSnapshot.value=null;scrollTop();return null}
 const payload=JSON.parse(JSON.stringify(form));delete payload.wizard_step;delete payload.slot_explicit
 for(const key of ['manual_score','confidential_kd','top_secret_kd','combat_score','strength_min','strength_max'])if(payload[key]==='')payload[key]=null
 payload.score_mode='auto';payload.manual_score=null
 if(!needsGear.value)for(const gear of GEAR_FIELDS){payload[gear.key]=null;payload['partner_'+gear.key+'_min']=null}
 if(form.goal!=='33任务')payload.tasks=[]
 return payload
}
async function finish(){if(props.busy)return;if(props.activeTicket){await openConflict();return}const payload=await preparePayload();if(!payload)return;if(!preview.value){emit('clear-error');preview.value=true;return}if(!props.busy)emit('submit',payload)}
</script>
